package com.ruoyi.medical.persistence;
import com.fasterxml.jackson.databind.JsonNode;import com.ruoyi.medical.contracts.*;import com.ruoyi.medical.identity.*;import jakarta.servlet.http.*;import org.springframework.web.bind.annotation.*;import org.springframework.boot.autoconfigure.condition.ConditionalOnExpression;
@RestController @ConditionalOnExpression("${medical.model-runtime.enabled:false} and ${medical.formal-invocation.enabled:false}")
public final class FormalVerificationWorkerController {
 private final ServiceCertificateIdentity identities;private final FormalVerificationWorkerService worker;private final FormalInvocationHttpSchema schema;
 public FormalVerificationWorkerController(ServiceCertificateIdentity i,FormalVerificationWorkerService w,FormalInvocationHttpSchema s){identities=i;worker=w;schema=s;}
 @PostMapping(value="/internal/v1/model-verification-workers/claim",consumes="application/json") public JsonNode claim(HttpServletRequest q,HttpServletResponse r)throws Exception{var b=body(q,"WorkerClaim");var data=worker.claim(q,b.required("tenant_id").textValue());return FormalInvocationResponses.envelope(data,data.required("found").booleanValue()?data.required("lease").required("revision").textValue():null,r);}
 @PostMapping(value="/internal/v1/model-verification-workers/issue",consumes="application/json") public JsonNode issue(HttpServletRequest q,HttpServletResponse r)throws Exception{var b=body(q,"WorkerIdentity");return FormalInvocationResponses.envelope(worker.issue(q,b.required("tenant_id").textValue(),b.required("verification_id").textValue()),"1",r);}
 @PostMapping(value="/internal/v1/model-verification-workers/status",consumes="application/json") public JsonNode status(HttpServletRequest q,HttpServletResponse r)throws Exception{var b=body(q,"WorkerIdentity");var data=worker.status(q,b.required("tenant_id").textValue(),b.required("verification_id").textValue());return FormalInvocationResponses.envelope(data,data.required("revision").textValue(),r);}
 private JsonNode body(HttpServletRequest q,String definition)throws Exception{identities.require(q);var h=q.getHeaders("X-Schema-Version");if(q.getQueryString()!=null||h==null||!h.hasMoreElements()||!"1.0.0".equals(h.nextElement())||h.hasMoreElements())throw new TenantAccessException(ErrorCode.SCHEMA_INVALID);return schema.read(definition,FormalInvocationController.body(q));}
 @ExceptionHandler(TenantAccessException.class)void denied(TenantAccessException e,HttpServletResponse r)throws java.io.IOException{new IdentityErrorResponseWriter().write(r,e.code()==ErrorCode.ACCESS_DENIED?403:409,e.code());}
}
